package com.fakelegacy.customer;

import java.sql.Timestamp;
import java.time.LocalDateTime;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class LoyaltyDao {

    @Autowired
    private JdbcTemplate jdbc;

    public int balance(long customerId) {
        Integer p = jdbc.queryForObject("select loyalty_points from customers where id = ?", Integer.class, customerId);
        return p == null ? 0 : p;
    }

    /** Returns the points actually credited; business customers never earn points. */
    public int earn(Customer customer, int points, String orderRef) {
        if (customer.isB2b()) {
            return 0;
        }
        jdbc.update("update customers set loyalty_points = loyalty_points + ? where id = ?", points, customer.getId());
        log(customer.getId(), points, "EARN", orderRef);
        return points;
    }

    /** points > 0 spends points (balance must cover them), points < 0 gives them back. */
    public boolean redeem(long customerId, int points, String orderRef) {
        if (points > 0) {
            int rows = jdbc.update("update customers set loyalty_points = loyalty_points - ? "
                    + "where id = ? and loyalty_points >= ?", points, customerId, points);
            if (rows == 0) {
                return false;
            }
        } else {
            jdbc.update("update customers set loyalty_points = loyalty_points - ? where id = ?", points, customerId);
        }
        log(customerId, -points, "REDEEM", orderRef);
        return true;
    }

    private void log(long customerId, int points, String kind, String orderRef) {
        jdbc.update("insert into loyalty_transactions (customer_id, points, kind, order_ref, created_at) values (?,?,?,?,?)",
                customerId, points, kind, orderRef, Timestamp.valueOf(LocalDateTime.now()));
    }
}
